```','2026-07-12 17:36:45','[{"provider": "diy", "ms": 7784, "results": 0, "ok": true, "error": null}, {"provider": "diy", "ms": 2413, "results": 0, "ok": true, "error": null}, {"provider": "diy", "ms": 1668, "results": 0, "ok": true, "error": null}, {"provider": "diy", "ms": 13636, "results": 2, "ok": true, "error": null}, {"provider": "diy", "ms": 12465, "results": 2, "ok": true, "error": null}, {"provider": "diy", "ms": 15704, "results": 2, "ok": true, "error": null}]','exp36_model_opus','[{"url": "https://ojs.aaai.org/index.php/ICWSM/article/view/18120", "snippet": "This paper presents three high quality social opinion datasets in the socio-economic domain, specifically Malta''s annual Government Budgets of 2018, 2019 and 2020. They contain over 6,000 online posts of user-generated content in English and/or Maltese, gathered from newswires and social networking services. These have been annotated for multiple opinion dimensions, namely subjectivity, sentiment polarity, emotion, sarcasm and irony, and in terms of negation, topic and language.", "title": "A Dataset of Multidimensional and Multilingual Social ...", "provider": "diy"}, {"url": "https://www.um.edu.mt/library/oar/handle/123456789/120597", "snippet": "This is true for companies that need to figure out how their target market reacts to their brand, for politicians to understand how they are perceived by potential voters and, in closer relation to this study, help governments understand the sentiment of its people during a worldwide pandemic. In this work, we go through several Facebook comments and Twitter posts to decipher the sentiment of Maltese citizens during the start of the COVID\u201019 pandemic, during the years 2019 and 2020. ... By understanding the sentiment of citizens, large entities such as the local government and large corporations can start to understand what the population needs and how to effectively aid in such a troubling time. By performing sentiment analysis and scraping relevant content posted by citizens, instead of asking predetermined questions, a particular element of bias is removed, allowing for deeper insight into the people\u2019s freely voiced concerns or opinions. ... | Keywords: | COVID-19 Pandemic, 2020-2023 -- Malta Data sets -- Malta Sentiment analysis -- Malta |", "title": "OAR@UM: Deciphering the sentiment of Maltese citizens ...", "provider": "diy"}, {"url": "https://researchguides.library.wisc.edu/c.php?g=1444230&p=10746789", "snippet": "\"About Dataset The Social Media Sentiments Analysis Dataset captures a vibrant tapestry of emotions, trends, and interactions across various social media platforms. This dataset provides a snapshot of user-generated content, encompassing text, timestamps, hashtags, countries, likes, and retweets. Each entry unveils unique stories\u2014moments of surprise, excitement, admiration, thrill, contentment, and more\u2014shared by individuals worldwide.\"", "title": "Social Media Research - Social Science Data - Research Guides", "provider": "diy"}, {"url": "https://github.com/Rajbharaman/Social-Media-Sentiment-Data-Analysis", "snippet": "About Dataset The Social Media Sentiments Analysis Dataset captures a vibrant tapestry of emotions, trends, and interactions across various social media platforms. This dataset provides a snapshot of user-generated content, encompassing text, timestamps, hashtags, countries, likes, and retweets. Each entry unveils unique stories\u2014moments of surprise, excitement, admiration, thrill, contentment, and more\u2014shared by individuals worldwide.", "title": "Rajbharaman/Social-Media-Sentiment-Data-Analysis - GitHub", "provider": "diy"}, {"url": "https://mediawatcher.ai/government-and-public-sector/", "snippet": "When a policy drops or a public statement goes out, Media Watcher shows you exactly how it''s being covered, which outlets picked it up, how they framed it, and whether the tone is accurate or adverse.", "title": "Government & Public Sector Media Intelligence", "provider": "diy"}]');
