INSERT OR IGNORE INTO phase2_researcher_runs (id,run_id,pair_run_id,question_id,country_code,retry_count,answer,answer_explanation,evidence_quote,source_url,retrieval_confidence,answer_confidence,search_queries_used,fetched_urls,domain_trust_score,language_route_used,notes,failure_mode,input_tokens,output_tokens,wall_clock_ms,estimated_cost_usd,condition_label,prompt_version_id,model_version,raw_response,created_at,search_provider_calls,experiment_id,search_snippets) VALUES (9173,'2206f8e0-e541-4243-8cd3-e3d74cb9edb3','fab2f1fb-c039-41d2-a841-6c643678740e','Q6','NL',0,'inconclusive','The only snippet discusses general EU interoperability frameworks and legislation but contains no evidence of specific Dutch measures ensuring high-value datasets ((EU) 2023/138) are interoperable with other countries'' datasets.','De EU is bezig om interoperabiliteitskaders voor het delen van informatie in de publieke sector vast te leggen in de wet.','https://www.digitaleoverheid.nl/overzicht-van-alle-onderwerpen/europa/europese-wet-en-regelgeving/',0.6,0.2,'["Netherlands high-value datasets interoperability cross-border 2023/138", "hoogwaardige datasets interoperabiliteit grensoverschrijdend Nederland", "site:data.overheid.nl high-value datasets interoperabiliteit"]','["https://www.digitaleoverheid.nl/overzicht-van-alle-onderwerpen/europa/europese-wet-en-regelgeving/"]',1.0,'native',NULL,NULL,3692,618,9818,0.03391,'opus_o48',22,'claude-opus-4-8','{
