INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3077,'d33b591d-8bc1-41bb-b348-3970d734682e','cd60b81f-cf13-4553-bf09-37ad01def66a','PT12','MT','accepted_by_verifier','yes','The Malta Data Portal''s Terms of Use explicitly states that automated notification functionality is available, allowing users to receive email notifications when information updates occur on the website.','This website may offer the service of automated notification on information updates within the website. The notifications functionality allows users to choose what to be notified and when to be notified on information changes. Notifications will be delivered via the email address provided by the user.','https://datainfo.gov.mt/en/terms-of-use/',0.85,0.9,3,0,0,34209,2779,38640,0.048103999999999994,NULL,'2026-07-12 13:19:14','exp32_model_haiku');
