INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3095,'d33b591d-8bc1-41bb-b348-3970d734682e','8c60a1f5-ccbc-4333-8590-f92e7d53aeae','I1','MT','abstained_adjudicator','inconclusive','Malta has defined open data reuse through CC BY 4.0 licensing terms that explicitly permit sharing, adaptation, and commercial use of open data.','Licensing the reporting contents under a CC BY 4.0 license means a user may: Share – copy and redistribute the material in any medium or format Adapt – remix, transform, and build upon the material, even commercially','https://energywateragency.gov.mt/eureporting-ccby/',0.75,0.65,3,1,0,38891,4446,60660,0.061120999999999995,NULL,'2026-07-12 13:25:30','exp32_model_haiku');
