INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3105,'d33b591d-8bc1-41bb-b348-3970d734682e','762ff89f-0e1a-40d4-ac34-54ee04607070','PT15','MT','abstained_adjudicator','inconclusive','The search results do not contain information about whether Malta''s open data team monitors the extent to which data requests result in publication of the requested data. The only snippet relates to EU Habitats Directive reporting, which is unrelated to the question.','The search results provided do not contain relevant evidence addressing whether Malta monitors the publication of requested data.','https://data.gov.mt/',0.3,0.1,3,1,0,38509,3191,42378,0.054464,NULL,'2026-07-12 13:29:01','exp32_model_haiku');
