INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3119,'d33b591d-8bc1-41bb-b348-3970d734682e','5a8082c7-c1aa-4bf1-a148-d1abea5930b4','Q4','MT','abstained_adjudicator','inconclusive','The search results do not contain information about Malta''s specific efforts or policies to ensure published data covers complete time series from first publication to present; references to SDDS Plus and GDPR retention relate to different data governance concerns.','On 31st July 2023, Malta became SDDS plus compliant. The SDDS Plus is the highest tier in the Fund''s Data Standards Initiatives','https://nso.gov.mt/special-data-dissemination/',0.85,0.3,3,1,0,37752,3853,54673,0.057017000000000005,NULL,'2026-07-12 13:34:09','exp32_model_haiku');
