INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3308,'2206f8e0-e541-4243-8cd3-e3d74cb9edb3','8329ba55-5c30-4741-996f-3d87233ac83f','I2','NL','abstained_adjudicator','inconclusive','The snippets show the Netherlands stimulates and supports open-data reuse via data.overheid.nl but none describe a concrete process that monitors the level of reuse, so no verbatim quote supports either a confident ''yes'' or ''no''.','De Rijksoverheid stimuleert het hergebruik van open data van de overheid.','https://www.digitaleoverheid.nl/overzicht-van-alle-onderwerpen/data/open-data/',0.7,0.35,3,1,0,34528,5146,85767,0.30129,NULL,'2026-07-12 18:20:51','exp36_model_opus');
