INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3310,'2206f8e0-e541-4243-8cd3-e3d74cb9edb3','09f4fcf1-9a0c-4ca6-b99c-1e292dfbe117','I5','NL','abstained_adjudicator','inconclusive','The Dutch government''s own 2021 impact assessment states there is no consensus on the definition of open data impact, indicating impact has not been specified in a strategy document.','Assessing the impact of open data is still generally considered a new field, with no consensus, for example, on the definition, or methodologies to measure impact.','https://data.overheid.nl/assessment-impact-data-2021',0.7,0.55,3,1,0,31267,4938,91639,0.279785,NULL,'2026-07-12 18:21:36','exp36_model_opus');
