INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3312,'2206f8e0-e541-4243-8cd3-e3d74cb9edb3','e35586ab-eb71-460c-95ea-73ce2ce05066','P28','NL','accepted_by_verifier','yes','The Dutch government runs the Rijks Data Science Programme as part of a formal action plan to train civil servants in data skills.','The Rijks Data Science Programme is part of an action plan of the Dutch government involving the recruitment of ICT professionals','https://www.cbs.nl/en-gb/corporate/2018/36/rijks-data-science-programme-kicks-off',0.8,0.72,0,0,0,7957,1160,25528,0.06878500000000001,NULL,'2026-07-12 18:22:58','exp36_model_opus');
INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3313,'2206f8e0-e541-4243-8cd3-e3d74cb9edb3','071bcf92-087a-4172-a4c6-ba9aa335c5df','PT23','NL','accepted_by_verifier','yes','The national data portal reports maintaining extensive statistics on user visits and clicks since 2019, indicating traffic monitoring.','Since 2019 we have an application catalogue for re-use and extensive statistics on user visits and clicks. This gives data owner great insights in the re-use of their data.','https://data.overheid.nl/assessment-impact-data-2021',0.6,0.7,0,0,0,7639,1089,21378,0.06542,NULL,'2026-07-12 18:23:07','exp36_model_opus');
