INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3319,'2206f8e0-e541-4243-8cd3-e3d74cb9edb3','a93d5f00-f38b-4a38-bda7-46bcdd330b8c','PT38','NL','accepted_by_verifier','yes','The national portal data.overheid.nl hosts multiple real-time datasets, including an API providing real-time information about open bridges and available harbour berths.','Open data service (API) met real-time, gratis informatie over openstaande bruggen.','https://data.overheid.nl/en/dataset/33049-actuele-brugopeningen-en-beschikbare-haven-ligplaatsen-api',0.95,0.95,0,0,0,9298,897,15138,0.068915,NULL,'2026-07-12 18:24:55','exp36_model_opus');
