INSERT OR IGNORE INTO phase2_final (id,run_id,pair_run_id,question_id,country_code,terminal_status,final_answer,final_answer_explanation,final_evidence_quote,final_source_url,final_retrieval_confidence,final_answer_confidence,retry_count,adjudicator_involved,captcha_escalated,cumulative_input_tokens,cumulative_output_tokens,cumulative_wall_clock_ms,cumulative_cost_usd,final_failure_reason,created_at,experiment_id) VALUES (3321,'2206f8e0-e541-4243-8cd3-e3d74cb9edb3','5a22348a-019a-40e5-bcd4-69f9bda34ac8','PT40','NL','accepted_by_verifier','yes','The Dutch portal explicitly hosts descriptions of ''closed'' datasets that are not available for public reuse, showing users what data exists but cannot be made available as open data.','Sommige datasets op data.overheid.nl zijn ''gesloten''. Dit betekent dat de dataset niet voor publiek hergebruik beschikbaar is of komt. Als een dataset ''gesloten'' is, moet ook duidelijk zijn waarom een dataset niet beschikbaar is of beschikbaar zal komen.','http://data.overheid.nl/ondersteuning/open-data/begrippenkader',0.9,0.85,0,0,0,8695,1285,22725,0.0756,NULL,'2026-07-12 18:25:20','exp36_model_opus');
